// Per-surface JNI state of `dev.nve.host.NativeRuntime` over `libnve_runtime` (ABI v4).
#pragma once

#include <jni.h>

#include <nve/generated/nve_abi.generated.h>
#include <nve/generated/nve_jni_frame.generated.hpp>
#include <nve/host/runtime_session.hpp>

// Generated by CMake from the Java sources (`dev.nve.host.generated.NveRuntimeAbi` /
// `NveJniFrame`): `static_assert`s every `STATUS_*`, the runtime schema hash, and the packed
// frame layout hash against this build's C / C++ halves, so a stale Java half fails the build.
#include "nve_java_contract.generated.hpp"

#include <array>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <thread>
#include <vector>

namespace nve::android {

/// `GlobalRef` `DirectByteBuffer` over native memory, recreated only when `(ptr, len)` changes.
class CachedDirectBuffer {
 public:
  /// Sets `*out` to the global ref for `[ptr, ptr + len)` (`nullptr` for an empty range). `false`
  /// on a JNI failure, with the pending exception cleared and `*out == nullptr`.
  [[nodiscard]] bool sync(JNIEnv* env, const void* ptr, size_t len, jobject* out);
  void release(JNIEnv* env) noexcept;

 private:
  const void* ptr_ = nullptr;
  size_t len_ = 0u;
  jobject ref_ = nullptr;
};

/// A Java callback target held as a `GlobalRef` with its resolved method.
struct JavaCallback {
  jobject target = nullptr;
  jmethodID method = nullptr;
  void release(JNIEnv* env) noexcept;
};

struct AndroidSurface {
  nve::host::RuntimeSession session;
  std::optional<nve::host::RuntimeSceneGuard> scene;
  JavaVM* jvm = nullptr;
  /// The thread that created the surface: the runtime's owner thread. `destroy` elsewhere is refused.
  std::thread::id owner_thread = std::this_thread::get_id();
  uint32_t surface_id = 1u;
  std::array<CachedDirectBuffer, nve::jni_frame::SLABS_LEN> slabs{};
  /// Tables packed by the previous `acquireScene`: only `[table_count, prev_table_count)` slab
  /// slots need clearing on the next one.
  uint32_t prev_table_count = 0u;
  std::vector<NveDirectEvent> events;
  JavaCallback measurer;
  jfloatArray measure_out = nullptr;
  JavaCallback wake;
  std::string last_error;
};

[[nodiscard]] inline AndroidSurface* surface_of(jlong handle) noexcept {
  return reinterpret_cast<AndroidSurface*>(handle);
}

/// Releases the held scene (every mutating call does this first so the runtime is never `Busy`).
void release_scene(AndroidSurface& s) noexcept;

/// Drops every cached slab `DirectByteBuffer` (app swap, pairing change, destroy).
void release_buffers(AndroidSurface& s, JNIEnv* env) noexcept;

/// Records `status` (with the runtime's message) as the surface's last error and returns it
/// (`NVE_RUNTIME_OK` clears the last error). Every JNI entry point returns a status, never a value.
jint status_of(AndroidSurface& s, NveRuntimeStatus status);

/// Writes `value` to `out[0]` when `out` is a non-empty array.
void write_out(JNIEnv* env, jintArray out, jint value);

/// UTF-8 copy of a Java string (`""` for null or on a JNI failure; lone surrogates become U+FFFD).
std::string utf8_of(JNIEnv* env, jstring str);

/// Java string of UTF-8 bytes (malformed sequences become U+FFFD; never modified UTF-8).
jstring java_string(JNIEnv* env, const uint8_t* utf8, size_t len);

/// `true` (and the exception cleared) when a JNI call left an exception pending.
inline bool clear_exception(JNIEnv* env) noexcept {
  if (!env->ExceptionCheck()) return false;
  env->ExceptionClear();
  return true;
}

}  // namespace nve::android
